12: /** 有界出站调度。相同聊天同时只发一条，发送前落盘 SENDING，未知送达绝不自动重发；账本只保存正文原文。 */
13: @Slf4j
14: public final class FeishuDeliveryService implements AutoCloseable {
15:     private static final int MAX_NOTICES = 128;
16:     private final FeishuTaskStore store;
17:     private final FeishuMessageSender sender;
18:     private final Clock clock;
19:     private final ExecutorService io = Executors.newFixedThreadPool(2,
20:             Thread.ofVirtual().name("feishu-send-", 0).factory());
21:     private final Map<String, Notice> notices = new LinkedHashMap<>();
22:     private final Set<String> inFlightChats = new HashSet<>();
23:     private volatile boolean closed;
24: 
25:     public FeishuDeliveryService(FeishuTaskStore store, FeishuMessageSender sender, Clock clock) {
26:         this.store = store; this.sender = sender; this.clock = clock;
27:     }
28: 
29:     /** 回执优先于最终结果，最终结果优先于心跳；短暂通知不积压重试。 */
30:     public synchronized void notice(Task task, String kind, String text, boolean urgent, BooleanSupplier valid) {
31:         if (closed || notices.size() >= MAX_NOTICES) return;
32:         String key = task.id() + ":" + kind;
33:         // 同一类待发提醒在本地合并，但每次实际提醒属于新消息，不能复用平台一小时去重 uuid。
34:         String deliveryId = kind.equals("heartbeat") || kind.equals("delivery-error")
35:                 ? UUID.randomUUID().toString() : stableId(key);
36:         notices.put(key, new Notice(task.chatId(), task.replyTo(), deliveryId, text,
37:                 clock.millis() + 30_000, urgent, valid, task.id(), kind, clock.millis()));
38:     }
39: 
40:     /** 丢弃某任务所有尚未发送的回执／进度；已在途平台请求无法保证撤回。 */
41:     public synchronized void discardNotices(String taskId) {
42:         notices.keySet().removeIf(key -> key.startsWith(taskId + ":"));
43:     }
44: 
45:     /** 每次最多占用两个聊天发送槽位，不把网络请求放在调度线程执行。 */
46:     public synchronized void pump() {
47:         if (closed || !store.healthy()) return;
48:         while (inFlightChats.size() < 2) {
49:             Work work = next();
50:             if (work == null) break;
51:             inFlightChats.add(work.chatId());
52:             try {
53:                 io.execute(() -> send(work));
54:             } catch (RejectedExecutionException exception) {
55:                 inFlightChats.remove(work.chatId());
56:                 // 若已领取最终段则保持 SENDING，下次启动按 UNKNOWN 恢复，不能假定尚未送达。
57:                 log.warn("飞书发送执行器已停止，保留待核对投递状态");
58:                 return;
59:             }
60:         }
61:     }
62: 
63:     private Work next() {
64:         Work urgent = nextNotice(true);
65:         if (urgent != null) return urgent;
66:         Set<String> blockedConversations = new HashSet<>();
67:         long now = clock.millis();
68:         // 控制命令和校验反馈不能被旧回复的 UNKNOWN 状态挡住，否则无法通过聊天解除投递暂停。
69:         List<Task> ordered = store.snapshot().tasks().stream()
70:                 .sorted(Comparator.comparing(task -> !"控制反馈".equals(task.stage()))).toList();
71:         for (Task task : ordered) {
72:             if (task.parts().isEmpty()) continue;
73:             // 控制反馈是解除投递暂停的唯一入口：既不能被别的回复的 UNKNOWN 挡住，也不能被自己历史段挡住。
74:             boolean control = "控制反馈".equals(task.stage());
75:             if (!control && blockedConversations.contains(task.conversation())) continue;
76:             for (int i = 0; i < task.parts().size(); i++) {
77:                 Part part = task.parts().get(i);
78:                 if (part.status() == Delivery.SENT) continue;
79:                 if (!control) blockedConversations.add(task.conversation());
80:                 if (inFlightChats.contains(task.chatId()) || part.status() == Delivery.SENDING
81:                         || part.status() == Delivery.FAILED || part.status() == Delivery.UNKNOWN
82:                         || part.retryAt() > now) break;
83:                 if (part.firstAttemptAt() > 0 && now - part.firstAttemptAt() >= 50 * 60_000L) {
84:                     setPart(task.id(), i, part.toBuilder().status(Delivery.UNKNOWN).errorCode("dedup_window_expired").build());
85:                     break;
86:                 }
87:                 Part claimed = part.toBuilder().status(Delivery.SENDING).attempts(part.attempts() + 1)
88:                         .firstAttemptAt(part.firstAttemptAt() == 0 ? now : part.firstAttemptAt()).build();
89:                 setPart(task.id(), i, claimed);
90:                 return new Work(task.chatId(), task.replyTo(), claimed.id(), claimed.text(), task.id(), i, null);
91:             }
92:         }
93:         return nextNotice(false);
94:     }
95: 
96:     private Work nextNotice(boolean urgent) {
97:         Iterator<Notice> iterator = notices.values().iterator();
98:         while (iterator.hasNext()) {
99:             Notice notice = iterator.next();
100:             if (notice.expiresAt() <= clock.millis() || !notice.valid().getAsBoolean()) {
101:                 iterator.remove(); continue;
102:             }
103:             if (notice.urgent() != urgent || inFlightChats.contains(notice.chatId())) continue;
104:             iterator.remove();
105:             return new Work(notice.chatId(), notice.replyTo(), notice.id(), notice.text(), null, -1, notice);
106:         }
107:         return null;
108:     }
109: 
110:     private void send(Work work) {
111:         try {
112:             if (closed || !store.healthy()) return;
113:             if (work.notice() != null && (work.notice().expiresAt() <= clock.millis()
114:                     || !work.notice().valid().getAsBoolean())) return;
115:             long started = System.nanoTime();
116:             // 提醒与控制反馈是普通文本；任务最终回复按其 Markdown 原样渲染。
117:             FeishuMessageSender.Attempt attempt = sender.send(work.chatId(), work.replyTo(), work.id(), work.text(),
118:                     work.notice() != null ? FeishuMessageSender.Format.TEXT : FeishuMessageSender.Format.MARKDOWN);
119:             long costMillis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started);
120:             if (work.taskId() == null) {
121:                 log.info("飞书状态投递：taskId={}, kind={}, status={}, queueMs={}, costMs={}",
122:                         work.notice().taskId(), work.notice().kind(), attempt.status(),
123:                         Math.max(0, clock.millis() - work.notice().queuedAt()), costMillis);
124:                 if (attempt.status() != FeishuMessageSender.Status.SENT) {
125:                     log.warn("飞书短暂状态通知未送达：status={}, code={}", attempt.status(), attempt.code());
126:                 }
127:                 return;
128:             }
129:             Task task = store.task(work.taskId());
130:             Part part = task.parts().get(work.partIndex());
131:             Part updated;
132:             switch (attempt.status()) {
133:                 case SENT -> updated = part.toBuilder().status(Delivery.SENT).messageId(attempt.messageId()).errorCode(null).build();
134:                 case RETRYABLE -> updated = part.toBuilder()
135:                         .status(part.attempts() >= 4 ? Delivery.FAILED : Delivery.RETRY_WAIT)
136:                         .retryAt(clock.millis() + Math.max(attempt.retryAfterMillis(), (long) Math.pow(3, part.attempts() - 1) * 1000))
137:                         .errorCode(attempt.code()).build();
138:                 case FAILED -> updated = part.toBuilder().status(Delivery.FAILED).errorCode(attempt.code()).build();
139:                 default -> updated = part.toBuilder().status(Delivery.UNKNOWN).errorCode(attempt.code()).build();
140:             }
141:             setPart(task.id(), work.partIndex(), updated);
142:             log.info("飞书正文投递：taskId={}, part={}, status={}, attempt={}, costMs={}",
143:                     task.id(), work.partIndex() + 1, updated.status(), updated.attempts(), costMillis);
144:             if (updated.status() == Delivery.UNKNOWN || updated.status() == Delivery.FAILED) {
145:                 log.warn("飞书最终回复投递暂停：taskId={}, part={}, status={}, code={}",
146:                         task.id(), work.partIndex(), updated.status(), updated.errorCode());
147:                 String text = updated.status() == Delivery.UNKNOWN
148:                         ? "回复发送状态不确定，已保留完整结果。补发可能重复；如确认补发，请发送 /resend " + task.id()
149:                         : "回复发送失败，已保留完整结果。修复权限或网络后，可发送 /retry " + task.id();
150:                 notice(task, "delivery-error", text, true, () -> true);

