150:         Instant now = automationClock.instant();
151:         repository.expire(owner, now);
152:         var local = now.atZone(ZoneId.of(s.timezone()));
153:         if (signals != null) signals.checkSignals(s, local, now);
154:         if (local.getHour() < 12 || !local.toLocalTime().isBefore(LocalTime.of(23, 30))) return;
155:         for (var c : repository.candidates(owner)) {
156:             if (!c.state().equals("PENDING")) continue;
157:             if (!now.isBefore(c.expiresAt())) {
158:                 repository.candidateState(owner, c.id(), "PENDING", "EXPIRED", null, ""); continue;
159:             }
160:             var content = repository.content(owner, c.contentId());
161:             if (content.isEmpty() || !LifeOutreachPolicy.isDeliverable(content.get())) {
162:                 repository.candidateState(owner, c.id(), "PENDING", "CANCELLED", null, ""); continue;
163:             }
164:             if (now.isBefore(due(c))) continue;
165:             // 冷启动：全域每日最多一次，同主题至少24小时；无新信息由唯一键阻止入队。
166:             if (repository.lastPresentation(owner).filter(sent -> now.isBefore(sent.plus(Duration.ofHours(24)))).isPresent()) continue;
167:             if (!repository.candidateState(owner, c.id(), "PENDING", "PRESENTED", now, "")) continue;
