172:     private void checkIdleNudge(Settings s, ZonedDateTime local, Instant now) {
173:         if (!s.idleCheckinEnabled()) return;
174:         int minHour = repository.habit(s.owner()).filter(h -> h.active() && now.isBefore(h.expiresAt()))
175:                 .map(Habit::availableHour).orElse(12);
176:         if (local.getHour() < minHour) return;
177:         if (repository.lastPresentation(s.owner()).filter(sent -> now.isBefore(sent.plus(Duration.ofHours(24)))).isPresent()) return;
178:         Instant lastActive = activity != null
179:                 ? activity.lastInteractionAt(s.owner(), local.getZone(), now).orElse(null)
180:                 : repository.latestUserActivity(s.owner()).orElse(null);
181:         Instant baseline = s.authorizedAt();
182:         if (lastActive != null && (baseline == null || lastActive.isAfter(baseline))) {
183:             baseline = lastActive;
184:         }
185:         if (baseline == null || Duration.between(baseline, now).toDays() < s.idleCheckinDays()) return;
186:         String dedupKey = "idle:" + baseline.truncatedTo(ChronoUnit.MINUTES);
187:         deliveries.sendNudge(s, "IDLE_CHECKIN", dedupKey, IDLE_CHECKIN_TEXT);
